
const Path = require("path");
const Pdf = require("pdf-parse.js");

module.exports = Pdf;

let isDebugMode = !module.parent;

// For testing purpose
if (isDebugMode) {
  // Dynamically resolve the path to the PDF file
  const PDF_FILE = Path.join(__dirname, "test", "data", "05-versions-space.pdf");

  // Check if the file exists
  if (!Fs.existsSync(PDF_FILE)) {
    console.error(`File not found: ${PDF_FILE}`);
    process.exit(1); // Exit the process if the file is not found
  }

  try {
    let dataBuffer = Fs.readFileSync(PDF_FILE);

    Pdf(dataBuffer)
      .then(function (data) {
        // Write the extracted text to a .txt file
        const outputFilePath = `${PDF_FILE}.txt`;
        Fs.writeFileSync(outputFilePath, data.text, {
          encoding: "utf8",
          flag: "w",
        });
        console.log(`Text extracted and saved to: ${outputFilePath}`);
      })
      .catch(function (err) {
        console.error("Error parsing PDF:", err.message);
      });
  } catch (err) {
    console.error("Error reading PDF file:", err.message);
  }
}
